// Chẩn đoán program mới khi chuyển bộ sau hâm nền: node bgdiff.mjs <repo> <dist> <query>
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const repo = process.argv[2], dist = process.argv[3], query = process.argv[4] || 'perf&lightsets=bg';
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page } = await lib.openApp(browser, srv.url + '?' + query, { width: 1920, height: 1080 });
try {
  // giữ ở full trong lúc hâm: ép ready giả về false mỗi khung không được (warm ghi true) ⇒ đặt mode khác? chỉ cần đặt đêm 0.5 (full) trong lúc hâm
  await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 0.5; });
  await page.waitForFunction(() => window.__app.lights.ready.night, null, { timeout: 120000, polling: 100 });
  await lib.frames(page, 30);
  const snap = () => page.evaluate(() => window.__app.renderer.info.programs.map((p) => p.name + '|' + p.cacheKey));
  let before = await snap();
  for (const [lab, n] of [['day', 0], ['night', 1], ['day2', 0], ['full', 0.5]]) {
    const t = await page.evaluate(async (n) => { const d = window.__app.dayNight; d.target = d.night = n; const t0 = performance.now(); await new Promise((ok) => requestAnimationFrame(() => requestAnimationFrame(ok))); return performance.now() - t0; }, n);
    await lib.frames(page, 10);
    const after = await snap(); const bs = new Set(before);
    const nu = after.filter((k) => !bs.has(k));
    console.log(`== ${lab}: 2 khung ${t.toFixed(0)} ms, +${nu.length} program`);
    for (const k of nu) {
      const [name, key] = k.split('|');
      // tìm key gần nhất (cùng tên) để thấy khác ở đâu
      const parts = key.split(','); let best = null, bd = 1e9;
      for (const o of before) { const [n2, k2] = o.split('|'); if (n2 !== name) continue; const p2 = k2.split(','); if (p2.length !== parts.length) continue; let d = 0; const diff = []; for (let i = 0; i < parts.length; i++) if (parts[i] !== p2[i]) { d++; diff.push(`${i}:${p2[i]}→${parts[i]}`); } if (d < bd) { bd = d; best = diff; } }
      console.log(`  ${name} khác ${bd}: ${best ? best.slice(0, 12).join(' ') : '(không có cùng tên)'}`);
    }
    before = after;
  }
} finally { await browser.close(); srv.close(); }

